return items.filter(item => {
  const categorias = item.json.categorie;

  // Asegura que sea un array
  if (Array.isArray(categorias)) {
    return categorias.includes("España") || categorias.includes("españa") || 
           categorias.includes("Mundo") || categorias.includes("mundo") || 
           categorias.includes("Economía") || categorias.includes("economía")|| 
           categorias.includes("Nacional") || categorias.includes("nacional")|| 
           categorias.includes("Internacional") || categorias.includes("internacional")
      ;
  }

  // Si es un string tipo "['Política', 'Economía']"
  try {
    const parsed = JSON.parse(categorias);
    return parsed.includes("España") || parsed.includes("españa") || 
           categorias.includes("Mundo") || categorias.includes("mundo") || 
           categorias.includes("Economía") || categorias.includes("economía")|| 
           categorias.includes("Nacional") || categorias.includes("nacional")|| 
           categorias.includes("Internacional") || categorias.includes("internacional")
  } catch (e) {
    // Si no es parseable, intentamos buscar como texto
    return categorias.includes("España") || categorias.includes("españa") || 
           categorias.includes("Mundo") || categorias.includes("mundo") || 
           categorias.includes("Economía") || categorias.includes("economía")|| 
           categorias.includes("Nacional") || categorias.includes("nacional")|| 
           categorias.includes("Internacional") || categorias.includes("internacional")
  }
});

