  const s = String($json.date);
  const norm = s.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
  const meses = {
    enero:1,febrero:2,marzo:3,abril:4,mayo:5,junio:6,
    julio:7,agosto:8,septiembre:9,setiembre:9,octubre:10,noviembre:11,diciembre:12
  };
  const m = norm.match(/(\d{1,2})\s+de\s+([a-z]+)\s+de\s+(\d{4})/i);
  if (!m) return ''; // o lanza error si prefieres
  const dd = m[1].padStart(2,'0');
  const mm = String(meses[m[2]] || '').padStart(2,'0');
  const yyyy = m[3];
  return `${yyyy}-${mm}-${dd}`;
})() }}

