  const categorias = item.json.categories;
    // Si categories es undefined, null o vacío, saltar este item
  if (categorias === undefined || categorias === null || categorias === '') {
    return false;
  }
  // Asegura que sea un array
  if (Array.isArray(categorias)) {
    return categorias.includes("Política") || categorias.includes("política") 
      ;
