  // Si es un string tipo "['Política', 'Economía']"
  try {
    const parsed = JSON.parse(categorias);
    return parsed.includes("Política") || parsed.includes("política") 
  } catch (e) {
    // Si no es parseable, intentamos buscar como texto
    return categorias.includes("Política") || categorias.includes("política") 
  }
});

